def solve():
    solutions = []
    for p in [3, 5, 7, 11, 13]:
        for a in range(1, 100):
            if a % p == 0: continue
            # a^{p-1} + b = p^k, b > a
            # So p^k > a^{p-1} + a
            # Let's try k from 1 to 10
            for k in range(1, 15):
                b = p**k - a**(p-1)
                if b > a and b > 0:
                    # Check if b^{p-1} + a is a power of p
                    val = b**(p-1) + a
                    # Check if val is a power of p
                    if val > 0:
                        # Use a simple check for power of p
                        temp_val = val
                        is_power = True
                        count = 0
                        while temp_val > 1:
                            if temp_val % p == 0:
                                temp_val //= p
                                count += 1
                            else:
                                is_power = False
                                break
                        if is_power and count > 0:
                            solutions.append((p, a, b))
    return solutions

print(solve())

def check_p_range():
    solutions = []
    # Try p up to 100
    for p in range(3, 101):
        if p > 2 and all(p % i != 0 for i in range(2, int(p**0.5) + 1)):
            # a must be \equiv -1 (mod p) and not divisible by p
            # Let's try a = np - 1
            for n in range(1, 1000):
                a = n * p - 1
                if a <= 0: continue
                ak_1 = a**(p-1)
                k = 1
                while True:
                    pk = p**k
                    b = pk - ak_1
                    if b <= a:
                        k += 1
                        continue
                    if b > 10**18:
                        break

                    val = b**(p-1) + a

                    temp_val = val
                    is_power = True
                    while temp_val > 1:
                        if temp_val % p == 0:
                            temp_val //= p
                        else:
                            is_power = False
                            break
                    if is_power and temp_val == 1:
                        solutions.append((p, a, b))
                    k += 1
                    if k > 60: break
    return solutions

print(check_p_range())

